import { clientIdFromKey } from "@galahad/core/identity";

/*
 * This browser's device identity: an ECDSA P-256 key pair generated by WebCrypto
 * as *non-extractable*. The private key can sign but can never be read out, not
 * even by this page's own code. It lives in IndexedDB as a CryptoKey object.
 */

export interface BrowserIdentity {
  device: string;
  privateKey: CryptoKey;
  publicKey: CryptoKey;
  enrolled: boolean;
  name: string;
}

const DB = "galahad";
const STORE = "identity";
const KEY = "self";

function openDb(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB, 1);
    request.onupgradeneeded = () => request.result.createObjectStore(STORE);
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

async function tx<T>(mode: IDBTransactionMode, run: (store: IDBObjectStore) => IDBRequest<T>): Promise<T> {
  const db = await openDb();
  try {
    return await new Promise<T>((resolve, reject) => {
      const request = run(db.transaction(STORE, mode).objectStore(STORE));
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    });
  } finally {
    db.close();
  }
}

export async function loadIdentity(): Promise<BrowserIdentity | null> {
  try {
    return ((await tx("readonly", (s) => s.get(KEY))) as BrowserIdentity | undefined) ?? null;
  } catch {
    return null;
  }
}

export async function saveIdentity(identity: BrowserIdentity): Promise<void> {
  await tx("readwrite", (s) => s.put(identity, KEY));
}

/** Deletes this browser's device key. It cannot be recovered; pairing again creates a new one. */
export async function forgetIdentity(): Promise<void> {
  await tx("readwrite", (s) => s.delete(KEY));
}

export function defaultDeviceName(): string {
  const ua = navigator.userAgent;
  const platform = /iPhone/.test(ua)
    ? "iPhone"
    : /iPad/.test(ua)
      ? "iPad"
      : /Android/.test(ua)
        ? "Android"
        : /Mac OS X/.test(ua)
          ? "Mac"
          : /Windows/.test(ua)
            ? "Windows"
            : /Linux/.test(ua)
              ? "Linux"
              : "device";
  const browser = /Edg\//.test(ua)
    ? "Edge"
    : /Firefox\//.test(ua)
      ? "Firefox"
      : /Chrome\//.test(ua)
        ? "Chrome"
        : /Safari\//.test(ua)
          ? "Safari"
          : "Browser";
  return `${browser} on ${platform}`;
}

export async function createIdentity(name = defaultDeviceName()): Promise<BrowserIdentity> {
  const pair = (await crypto.subtle.generateKey({ name: "ECDSA", namedCurve: "P-256" }, false, ["sign", "verify"])) as CryptoKeyPair;
  const raw = new Uint8Array(await crypto.subtle.exportKey("raw", pair.publicKey));
  const identity: BrowserIdentity = {
    device: clientIdFromKey(raw),
    privateKey: pair.privateKey,
    publicKey: pair.publicKey,
    enrolled: false,
    name,
  };
  await saveIdentity(identity);
  return identity;
}

export const signerFor =
  (identity: BrowserIdentity) =>
  async (message: Uint8Array<ArrayBuffer>): Promise<Uint8Array> =>
    new Uint8Array(await crypto.subtle.sign({ name: "ECDSA", hash: "SHA-256" }, identity.privateKey, message));
